using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long r, c;
    int k;
    cin >> r >> c >> k;
    // Every black cell touches at most four 2x2 windows (keyed by their top-left corner);
    // after sorting, a window's run length is its black-cell count.
    vector<long long> touched;
    touched.reserve(4 * (size_t)k);
