        long long x, y;
        cin >> x >> y;
        for (long long i = x - 1; i <= x; i++)
            for (long long j = y - 1; j <= y; j++)
                if (0 <= i && i < r - 1 && 0 <= j && j < c - 1) touched.push_back(i * 1000000000LL + j);
    }
    sort(touched.begin(), touched.end());
    long long ans[5] = {0}, distinct = 0;
    for (size_t i = 0; i < touched.size();) {
        size_t j = i;
        while (j < touched.size() && touched[j] == touched[i]) j++;
        ans[j - i]++;
        distinct++;
        i = j;
    }
    ans[0] = (r - 1) * (c - 1) - distinct;
    cout << ans[0] << " " << ans[1] << " " << ans[2] << " " << ans[3] << " " << ans[4] << "\n";
