import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static long next() {
        while (buf[pos] != '-' && (buf[pos] < '0' || buf[pos] > '9')) pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long x = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') x = x * 10 + (buf[pos++] - '0');
        return neg ? -x : x;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        long r = next(), c = next();
        int k = (int) next();
        // Every black cell touches at most four 2x2 windows (keyed by their top-left corner);
        // after sorting, a window's run length is its black-cell count.
        long[] touched = new long[4 * k];
        int size = 0;
        for (int t = 0; t < k; t++) {
            long x = next(), y = next();
            for (long i = x - 1; i <= x; i++)
                for (long j = y - 1; j <= y; j++)
                    if (0 <= i && i < r - 1 && 0 <= j && j < c - 1) touched[size++] = i * 1000000000L + j;
        }
        Arrays.sort(touched, 0, size);
        long[] ans = new long[5];
        long distinct = 0;
        for (int i = 0; i < size; ) {
            int j = i;
            while (j < size && touched[j] == touched[i]) j++;
            ans[j - i]++;
            distinct++;
            i = j;
        }
        ans[0] = (r - 1) * (c - 1) - distinct;
        System.out.println(ans[0] + " " + ans[1] + " " + ans[2] + " " + ans[3] + " " + ans[4]);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"slices"
)

var data []byte
var pos int

func next() int64 {
	for data[pos] != '-' && (data[pos] < '0' || data[pos] > '9') {
		pos++
	}
	neg := data[pos] == '-'
	if neg {
		pos++
	}
	var x int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		x = x*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -x
	}
	return x
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	r, c, k := next(), next(), int(next())
	// Every black cell touches at most four 2x2 windows (keyed by their top-left corner);
	// after sorting, a window's run length is its black-cell count.
	touched := make([]int64, 0, 4*k)
	for t := 0; t < k; t++ {
		x, y := next(), next()
		for i := x - 1; i <= x; i++ {
			for j := y - 1; j <= y; j++ {
				if 0 <= i && i < r-1 && 0 <= j && j < c-1 {
					touched = append(touched, i*1000000000+j)
				}
			}
		}
	}
	slices.Sort(touched)
	var ans [5]int64
	var distinct int64
	for i := 0; i < len(touched); {
		j := i
		for j < len(touched) && touched[j] == touched[i] {
			j++
		}
		ans[j-i]++
		distinct++
		i = j
	}
	ans[0] = (r-1)*(c-1) - distinct
	fmt.Println(ans[0], ans[1], ans[2], ans[3], ans[4])
}
